import {form,text,select as sel,download} from '../ui.mjs';
import {worksheetPages,coloringThemes} from './worksheets-core.mjs';
import {vectorResult,printVectorPages,svgPNG} from './vector.mjs';
export function setupWorksheets(tool,mount,out){let timer;const startType=['alphabet','math','handwriting','coloring'].includes(location.hash.slice(1))?location.hash.slice(1):'alphabet';const fields=[sel('type','Worksheet type',[['alphabet','Alphabet · A–Z'],['math','Math practice'],['handwriting','Handwriting tracing'],['coloring','Coloring pages']],startType),sel('paper','Paper size',[['a4','A4'],['letter','US Letter']],'a4'),{...text('name','Child’s first name (optional)','','text',true),required:false},sel('alphabetMode','Alphabet page',[['all','Full alphabet A–Z'],['focus','Practice one letter']],'all'),text('letter','Focus letter','A'),sel('operation','Arithmetic',[['add','Addition'],['subtract','Subtraction · no negative answers'],['multiply','Multiplication · tables 0–12'],['mixed','Mixed practice']],'add'),sel('limit','Number limit for addition / subtraction',[10,20,100],10),sel('count','Number of questions',[12,20,30],20),sel('key','Include answer key',[['yes','Yes · separate page'],['no','Worksheet only']],'yes'),text('seed','Question set','practice-1'),text('practice','Words to trace','Small steps, big possibilities.','text',true),sel('theme','Coloring picture',coloringThemes.map(id=>[id,id[0].toUpperCase()+id.slice(1)]),'cat')];
 const f=form(mount,fields,v=>{const r=worksheetPages(v);vectorResult(out,r.pages[0],'nepocore-'+r.type+'-worksheet',{width:r.width*2,height:r.height*2,label:'Ready for a little learning',details:[['Paper',v.paper==='a4'?'A4':'US Letter'],['Pages',r.pages.length],['PNG size',r.width*2+' × '+r.height*2+' px']],note:'Print at actual size and turn off browser headers and footers. Download PDF saves the full set, including an optional math answer key. “Print / Save PDF” opens your browser’s print dialog. Your entries are not saved by this tool.'});printVectorPages(out,r.pages,v.paper);if(r.pages[1]){const preview=document.createElement('details');preview.className='worksheet-key';preview.innerHTML='<summary>Preview answer key</summary><div class="vector-preview">'+r.pages[1]+'</div>';out.append(preview);for(const type of ['PNG','SVG']){const b=document.createElement('button');b.type='button';b.className='btn secondary small';b.textContent='Answer key '+type;b.onclick=async()=>{b.disabled=true;try{const blob=type==='SVG'?new Blob([r.pages[1]],{type:'image/svg+xml'}):await svgPNG(r.pages[1],r.width*2,r.height*2);if(b.isConnected)download(blob,'nepocore-math-answer-key.'+type.toLowerCase());}finally{if(b.isConnected)b.disabled=false;}};out.querySelector('.result-actions').append(b);}}},{label:'Create worksheet',note:'Four useful kinds of practice, ready to print. These are practice sheets, not a graded curriculum.'});
 f.elements.name.maxLength=35;f.elements.practice.maxLength=80;f.elements.letter.maxLength=1;f.elements.seed.maxLength=24;
 const groups={alphabet:['alphabetMode','letter'],math:['operation','limit','count','key','seed'],handwriting:['practice'],coloring:['theme']};
 function fieldsForType(){for(const [type,names]of Object.entries(groups))for(const name of names){const el=f.elements[name],visible=f.elements.type.value===type&&(name!=='letter'||f.elements.alphabetMode.value==='focus');el.closest('.field').hidden=!visible;el.disabled=!visible;}random.hidden=f.elements.type.value!=='math';}
 const random=document.createElement('button');random.type='button';random.className='btn secondary';random.textContent='New questions';f.querySelector('.form-actions').append(random);random.onclick=()=>{f.elements.seed.value=crypto.getRandomValues(new Uint32Array(1))[0].toString(16);f.requestSubmit();};
 f.addEventListener('change',()=>{fieldsForType();clearTimeout(timer);f.requestSubmit();});f.addEventListener('input',()=>{clearTimeout(timer);timer=setTimeout(()=>{if(f.isConnected)f.requestSubmit();},180);});f.addEventListener('reset',()=>setTimeout(fieldsForType,0));fieldsForType();return()=>clearTimeout(timer);
}
